<script setup>
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import InputLabel from '@/Components/InputLabel.vue';
import InputError from '@/Components/InputError.vue';
import PrimaryButton from '@/Components/PrimaryButton.vue';
import TextInput from '@/Components/TextInput.vue';
import { Head, useForm } from '@inertiajs/vue3';
const props = defineProps({ profile: Object });
const form = useForm({ nama_lengkap: props.profile?.nama_lengkap ?? '', nomor_ktp: props.profile?.nomor_ktp ?? '', alamat: props.profile?.alamat ?? '', email: props.profile?.email ?? '', nomor_whatsapp: props.profile?.nomor_whatsapp ?? '', nama_bank: props.profile?.nama_bank ?? '', nomor_rekening: props.profile?.nomor_rekening ?? '', atas_nama_rekening: props.profile?.atas_nama_rekening ?? '', tanda_tangan: null });
function submit() { form.post('/pengaturan/profil', { forceFormData: true, method: 'put' }); }
</script>
<template><Head title="Profil freelancer"/><AuthenticatedLayout><template #header><div><p class="text-sm text-slate-500">Pengaturan</p><h1 class="text-2xl font-semibold text-slate-900">Profil freelancer</h1></div></template><main class="mx-auto max-w-4xl px-4 py-8"><form @submit.prevent="submit" class="grid gap-5 rounded-2xl border border-slate-200 bg-white p-6 shadow-sm sm:grid-cols-2"><div><InputLabel for="name" value="Nama lengkap"/><TextInput id="name" v-model="form.nama_lengkap" required class="mt-1 block w-full"/><InputError :message="form.errors.nama_lengkap"/></div><div><InputLabel for="email" value="Email"/><TextInput id="email" type="email" v-model="form.email" required class="mt-1 block w-full"/><InputError :message="form.errors.email"/></div><div><InputLabel for="ktp" value="Nomor KTP"/><TextInput id="ktp" v-model="form.nomor_ktp" class="mt-1 block w-full"/></div><div><InputLabel for="wa" value="Nomor WhatsApp"/><TextInput id="wa" v-model="form.nomor_whatsapp" required class="mt-1 block w-full"/></div><div><InputLabel for="bank" value="Nama bank"/><TextInput id="bank" v-model="form.nama_bank" class="mt-1 block w-full"/></div><div><InputLabel for="rekening" value="Nomor rekening"/><TextInput id="rekening" v-model="form.nomor_rekening" class="mt-1 block w-full"/></div><div><InputLabel for="atasnama" value="Atas nama rekening"/><TextInput id="atasnama" v-model="form.atas_nama_rekening" class="mt-1 block w-full"/></div><div><InputLabel for="sign" value="Tanda tangan (PNG/JPG)"/><input id="sign" type="file" accept="image/png,image/jpeg" @input="form.tanda_tangan = $event.target.files[0]" class="mt-2 block text-sm"/><InputError :message="form.errors.tanda_tangan"/></div><div class="sm:col-span-2"><InputLabel for="alamat" value="Alamat"/><textarea id="alamat" v-model="form.alamat" rows="3" class="mt-1 block w-full rounded-md border-slate-300"/></div><div class="sm:col-span-2 flex justify-end"><PrimaryButton :disabled="form.processing">Simpan profil</PrimaryButton></div></form></main></AuthenticatedLayout></template>
